CREATE FUNCTION journal_changed() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
DECLARE source jsonb; journal_owner text; next_revision bigint; changed_key jsonb;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  IF TG_OP = 'DELETE' THEN source := to_jsonb(OLD); ELSE source := to_jsonb(NEW); END IF;
  journal_owner := source->>'owner_id';
  INSERT INTO journal_sync_revisions (owner_id, value) VALUES (journal_owner, 1)
  ON CONFLICT (owner_id) DO UPDATE SET value = journal_sync_revisions.value + 1
  RETURNING value INTO next_revision;
  SELECT jsonb_object_agg(key_column, source->key_column) INTO changed_key FROM unnest(TG_ARGV) AS key_column;
  INSERT INTO journal_changes (owner_id, table_name, row_key, revision)
  VALUES (journal_owner, TG_TABLE_NAME, changed_key::text, next_revision)
  ON CONFLICT (owner_id, table_name, row_key) DO UPDATE SET revision = excluded.revision;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
